/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-button-group {
  font-family: var(--ui-font-family, inherit);
  color: var(--ui-text, #171717);
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
  letter-spacing: var(--ui-type-label-letter-spacing, -0.01em);
  box-sizing: border-box;
}
:where([data-moru-registry]) .ui-button-group {
  display: inline-flex;
  align-items: stretch;
  max-width: 100%;
  isolation: isolate;
}
:where([data-moru-registry]) .ui-button-group > * {
  min-width: 0;
  position: relative;
}
:where([data-moru-registry]) .ui-button-group > :focus-visible {
  z-index: 1;
}
:where([data-moru-registry]) .ui-button-group[data-orientation='horizontal'] > :not(:first-child) {
  margin-inline-start: calc(-1 * var(--ui-border-width, 1px));
  border-start-start-radius: 0;
  border-end-start-radius: 0;
}
:where([data-moru-registry]) .ui-button-group[data-orientation='horizontal'] > :not(:last-child) {
  border-start-end-radius: 0;
  border-end-end-radius: 0;
}
:where([data-moru-registry]) .ui-button-group[data-orientation='vertical'] {
  flex-direction: column;
}
:where([data-moru-registry]) .ui-button-group[data-orientation='vertical'] > :not(:first-child) {
  margin-block-start: calc(-1 * var(--ui-border-width, 1px));
  border-start-start-radius: 0;
  border-start-end-radius: 0;
}
:where([data-moru-registry]) .ui-button-group[data-orientation='vertical'] > :not(:last-child) {
  border-end-start-radius: 0;
  border-end-end-radius: 0;
}
:where([data-moru-registry]) .ui-button-group-text {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 var(--ui-control-padding-x-md, 12px);
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: var(--ui-radius, 6px);
  background: var(--ui-background, #fafafa);
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { forwardRef, type HTMLAttributes } from 'react'
import { cn } from './_lib/cn'
import './controls-shared.css'
import './button-group.css'

export type ButtonGroupProps = HTMLAttributes<HTMLDivElement> & {
  orientation?: 'horizontal' | 'vertical'
}

export const ButtonGroup = forwardRef<HTMLDivElement, ButtonGroupProps>(function ButtonGroup(
  { orientation = 'horizontal', className, role = 'group', ...props },
  ref,
) {
  return (
    <div
      {...props}
      ref={ref}
      role={role}
      className={cn('ui-button-group', className)}
      data-orientation={orientation}
    />
  )
})

export function ButtonGroupText({ className, ...props }: HTMLAttributes<HTMLSpanElement>) {
  return <span {...props} className={cn('ui-button-group-text', className)} />
}
